<?php get_header(); ?><main id="top" class="section" style="padding-top:140px"><div class="container"><div class="section-head"><span class="eyebrow">Latest updates</span><h1><?php bloginfo('name'); ?></h1></div><div class="news-side"><?php if (have_posts()): while(have_posts()): the_post(); ?><article <?php post_class('mini-news reveal visible'); ?>><span class="date"><?php echo esc_html(get_the_date()); ?></span><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></article><?php endwhile; the_posts_pagination(); else: ?><p>No posts yet.</p><?php endif; ?></div></div></main><?php get_footer(); ?>
